const item = $input.first().json;
const payload = item.body ? item.body : item;

const rawSender = payload.from || payload.sender || payload.sender_email || "guest@enterprise.com";
const senderMatch = String(rawSender).match(/<([^>]+)>/);
const cleanSender = (senderMatch ? senderMatch[1] : String(rawSender)).trim().toLowerCase();
const senderName = payload.name || (senderMatch ? rawSender.split('<')[0].trim() : cleanSender.split('@')[0]);

const rawBody = payload.text || payload.body || payload.content || "";
const cleanBody = String(rawBody).replace(/<[^>]*>?/gm, '').trim();
const subject = String(payload.subject || "Không có tiêu đề").trim();
const receivedAt = new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh', hour12: false });

const securityEmailSubject = `🚨 [SECURITY SOC] CẢNH BÁO AN NINH: Phát hiện & Cách ly Thư từ ${cleanSender}`;

const securityEmailText = `[CẢNH BÁO AN NINH EMAIL DOANH NGHIỆP - ENTERPRISE SOC]
Kính gửi Quản trị viên An ninh Hệ thống,

Hệ thống lọc thư tự động vừa phát hiện và chặn đứng một bức thư gửi từ nguồn nguy hiểm:
- Địa chỉ người gửi: ${cleanSender}
- Tiêu đề thư: ${subject}
- Thời điểm tiếp nhận: ${receivedAt}
- Trạng thái xử lý: ĐÃ CÁCH LY THÀNH CÔNG vào bảng email_quarantine_vault.

Hành động khuyến nghị:
1. Kiểm tra chi tiết tại Cổng Quản Trị Helpdesk CRM: http://localhost:3000/tickets
2. Không mở bất kỳ tệp đính kèm nào từ người gửi này.

Trân trọng,
Bộ phận An ninh Hạ tầng Enterprise SOC`;

const securityEmailHtml = `<!DOCTYPE html>
<html lang="vi">
<head><meta charset="UTF-8"><title>Cảnh Báo An Ninh</title></head>
<body style="margin:0;padding:0;background-color:#0b0f19;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;color:#1e293b;">
  <table role="presentation" width="100%" cellspacing="0" cellpadding="0" style="padding:40px 15px;">
    <tr><td align="center">
      <table role="presentation" width="640" cellspacing="0" cellpadding="0" style="background:#ffffff;border-radius:16px;overflow:hidden;box-shadow:0 20px 40px rgba(0,0,0,0.4);max-width:640px;width:100%;">
        <tr>
          <td style="background:linear-gradient(135deg, #991b1b 0%, #dc2626 100%);padding:30px 40px;text-align:center;color:#ffffff;">
            <div style="font-size:12px;font-weight:bold;letter-spacing:1px;text-transform:uppercase;margin-bottom:8px;">🛡️ CYBER SECURITY &bull; ENTERPRISE SOC</div>
            <h1 style="margin:0;font-size:22px;font-weight:900;">CẢNH BÁO AN NINH HỆ THỐNG</h1>
            <p style="margin:8px 0 0 0;font-size:14px;opacity:0.9;">Phát hiện thư rác/phishing độc hại được đưa vào vùng cách ly</p>
          </td>
        </tr>
        <tr>
          <td style="padding:30px 40px;">
            <table width="100%" cellspacing="0" cellpadding="8" style="font-size:14px;background:#f8fafc;border-radius:10px;border:1px solid #e2e8f0;">
              <tr><td width="30%" style="font-weight:bold;color:#64748b;">Người gửi vi phạm:</td><td style="color:#b91c1c;font-weight:bold;">${cleanSender}</td></tr>
              <tr><td style="font-weight:bold;color:#64748b;">Tiêu đề thư:</td><td style="color:#0f172a;">${subject}</td></tr>
              <tr><td style="font-weight:bold;color:#64748b;">Thời điểm chặn:</td><td style="color:#0f172a;">${receivedAt}</td></tr>
              <tr><td style="font-weight:bold;color:#64748b;">Khu vực cách ly:</td><td style="color:#059669;font-weight:bold;">email_quarantine_vault</td></tr>
            </table>
            <div style="margin-top:24px;text-align:center;">
              <a href="http://localhost:3000/tickets" style="background:#dc2626;color:#ffffff;text-decoration:none;padding:12px 28px;border-radius:8px;font-weight:bold;font-size:14px;display:inline-block;">Kiểm Tra Bảng Điều Khiển An Ninh</a>
            </div>
          </td>
        </tr>
      </table>
    </td></tr>
  </table>
</body>
</html>`;

return [{
  json: {
    ...payload,
    sender_email: cleanSender,
    sender_name: senderName,
    subject: subject,
    clean_body: cleanBody,
    received_at: receivedAt,
    security_email_subject: securityEmailSubject,
    security_email_text: securityEmailText,
    security_email_html: securityEmailHtml
  }
}];

const item = $input.first().json;
const email = (item.sender_email || "").toLowerCase();
const subject = (item.subject || "").toLowerCase();

const isSystem = email.includes("no-reply") || 
                 email.includes("noreply") || 
                 email.includes("mailer-daemon") || 
                 email.includes("postmaster") || 
                 email.includes("bounce") ||
                 subject.includes("delivery status notification") ||
                 subject.includes("undelivered mail");

return [{
  json: {
    ...item,
    is_system_bounce: isSystem,
    system_bounce_reason: isSystem ? "Email hệ thống tự sinh / Bounce Mailer-Daemon" : null
  }
}];

