={{ (function() {
  const norm = $('2. Payload Normalization Code').first().json;
  const bounce = $('3. Filter System Bounces Code').first().json;
  const rep = $('4. Check Sender Reputation Postgres').first().json;
  const aiResp = $json;

  let isSpam = false;
  let reason = '';

  if (aiResp && aiResp.candidates && aiResp.candidates[0]?.content?.parts?.[0]?.text) {
    try {
      const parsed = JSON.parse(aiResp.candidates[0].content.parts[0].text);
      isSpam = parsed.is_spam === true || parsed.threat_type !== 'CLEAN';
      reason = parsed.quarantine_reason || parsed.threat_type;
    } catch(e) {}
  } else {
    const text = (norm.subject + ' ' + norm.clean_body).toLowerCase();
    isSpam = text.includes('crypto') || text.includes('trúng thưởng') || text.includes('tiền số') || text.includes('phishing');
    if (isSpam) reason = 'Phát hiện từ khóa lừa đảo / spam';
  }

  const isBounce = bounce.is_system_bounce === true;
  const repScore = rep.reputation_score !== undefined ? Number(rep.reputation_score) : 100;
  const isBlacklist = rep.status === 'blacklist' || rep.is_blocked === true || repScore < 20;

  if (isBounce) return 'QUARANTINE_BOUNCE';
  if (isBlacklist) return 'QUARANTINE_BLACKLIST';
  if (isSpam) return 'QUARANTINE_AI_SPAM';
  return 'CLEAN';
})() }}

